        TextNode node = new TextNode("Hello World");
        assertEquals(new TextNode("<p> Hello  <br> World</p>"), node.splitText(2));
    }

    public void testSplitTextWithOffset_2() {
        TextNode node = new TextNode("Hello World");
        assertEquals(new TextNode("<p> <b>Hello</b> <span>World</span></p>"), node.splitText(4));
    }

