        TextNode node = new TextNode("<html><body>Hello World!</body></html>");
        assertEquals(node.getText(), "Hello World!");
        node = new TextNode("<p>Hello<br>World</p>");
        assertEquals(node.getText(), "Hello World");
    }

    public void testGetWholeTextBlankLine() {
